package workstore

// Each SELECT is deliberately explicit and limited by the selected personal
// scope or an exact FK to it. No unknown table is exported by discovery.
var personalExportQueries = []personalExportQuery{
	{"scopes", `SELECT rowid,id,revision,payload FROM scopes WHERE id=?1 AND kind='personal'`},
	{"personal_scoped_content", `SELECT rowid,id,0,json_object('content_ref',id) FROM content WHERE scope_id=?1`},
	{"personal_migration_fences", `SELECT rowid,scope_id,revision,json_object('scope_id',scope_id,'migration_id',migration_id,'state',state,'revision',revision,'created_at',created_at,'updated_at',updated_at) FROM personal_migration_fences WHERE scope_id=?1`},
	{"personal_migration_preserved", `SELECT rowid,json_array(kind,record_id),record_revision,json_object('kind',kind,'record_id',record_id,'record_revision',record_revision,'payload_hash',payload_hash,'payload',json(payload),'created_at',created_at) FROM personal_migration_preserved WHERE scope_id=?1`},
	{"personal_migration_read_archives", `SELECT rowid,operation_id,revision,json_object('scope_id',scope_id,'operation_id',operation_id,'revision',revision,'operation_payload',json(operation_payload),'command_payload',json(command_payload),'process_payload',json(process_payload),'evidence_hash',evidence_hash,'observed_at',observed_at) FROM personal_migration_read_archives WHERE scope_id=?1`},
	{"personal_migration_publication_holds", `SELECT rowid,outbox_id,outbox_revision,json_object('scope_id',scope_id,'outbox_id',outbox_id,'operation_id',operation_id,'outbox_revision',outbox_revision,'operation_revision',operation_revision,'outbox_payload',json(outbox_payload),'operation_payload',json(operation_payload),'intake_proof_id',intake_proof_id,'evidence_hash',evidence_hash,'created_at',created_at) FROM personal_migration_publication_holds WHERE scope_id=?1`},
	{"personal_migration_reaction_holds", `SELECT rowid,reaction_id,reaction_revision,json_object('scope_id',scope_id,'reaction_id',reaction_id,'reaction_revision',reaction_revision,'reaction_payload',json(reaction_payload),'intake_proof_id',intake_proof_id,'evidence_hash',evidence_hash,'created_at',created_at) FROM personal_migration_reaction_holds WHERE scope_id=?1`},
	{"personal_migration_control_holds", `SELECT rowid,operation_id,operation_revision,json_object('scope_id',scope_id,'operation_id',operation_id,'operation_revision',operation_revision,'operation_payload',json(operation_payload),'evidence',json(evidence),'intake_proof_id',intake_proof_id,'evidence_hash',evidence_hash,'created_at',created_at) FROM personal_migration_control_holds WHERE scope_id=?1`},
	{"personal_migration_execution_holds", `SELECT rowid,worker_id,worker_revision,json_object('scope_id',scope_id,'worker_id',worker_id,'worker_revision',worker_revision,'worker_payload',json(worker_payload),'process_payload',json(process_payload),'intake_proof_id',intake_proof_id,'evidence',json(evidence),'evidence_hash',evidence_hash,'created_at',created_at) FROM personal_migration_execution_holds WHERE scope_id=?1`},
	{"authority", `SELECT rowid,legacy_key,generation,json_object('legacy_key',legacy_key,'generation',generation,'scope_id',scope_id,'state',state,'payload',json(payload)) FROM authority WHERE scope_id=?1`},
	{"principals", `SELECT rowid,id,revision,payload FROM principals WHERE id=(SELECT principal_id FROM scopes WHERE id=?1)`},
	{"roles", `SELECT rowid,id,revision,payload FROM roles WHERE id=(SELECT role_id FROM scopes WHERE id=?1)`},
	{"role_settings_references", `SELECT rowid,role_id,settings_revision,json_object('role_id',role_id,'source_hash',source_hash,'settings_revision',settings_revision) FROM role_settings_references WHERE role_id=(SELECT role_id FROM scopes WHERE id=?1)`},
	{"role_bot_bindings", `SELECT rowid,id,revision,payload FROM role_bot_bindings WHERE id=(SELECT role_id FROM scopes WHERE id=?1)`},
	{"external_identities", `SELECT x.rowid,json_array(x.tenant,x.domain,x.id_type,x.external_id,x.generation),0,json_object('tenant',x.tenant,'domain',x.domain,'id_type',x.id_type,'external_id',x.external_id,'generation',x.generation,'principal_id',x.principal_id,'evidence_ref',x.evidence_ref) FROM external_identities x WHERE x.principal_id=(SELECT principal_id FROM scopes WHERE id=?1) AND EXISTS (SELECT 1 FROM raw_ingress r JOIN ingress_observations i ON i.ingress_id=r.id WHERE json_extract(r.payload,'$.route.scope_id')=?1 AND json_extract(i.payload,'$.envelope.tenant')=x.tenant AND ((x.id_type='open_id' AND x.external_id=json_extract(i.payload,'$.envelope.sender_ids.open_id') AND x.domain=json_extract(i.payload,'$.gateway.app_id') AND x.generation=json_extract(i.payload,'$.gateway.bot_generation')) OR (x.id_type='user_id' AND x.external_id=json_extract(i.payload,'$.envelope.sender_ids.user_id') AND x.domain='tenant' AND x.generation=1) OR (x.id_type='union_id' AND x.external_id=json_extract(i.payload,'$.envelope.sender_ids.union_id') AND ((coalesce(json_extract(i.payload,'$.gateway.union_domain'),'')='' AND x.domain=json_extract(i.payload,'$.gateway.app_id') AND x.generation=json_extract(i.payload,'$.gateway.bot_generation')) OR (coalesce(json_extract(i.payload,'$.gateway.union_domain'),'')<>'' AND x.domain='union:'||json_extract(i.payload,'$.gateway.union_domain') AND x.generation=1)))))`},
	{"private_navigation", `SELECT rowid,scope_id,revision,payload FROM private_navigation WHERE scope_id=?1`},
	{"contexts", `SELECT rowid,id,revision,payload FROM contexts WHERE scope_id=?1`},
	{"context_preferences", `SELECT rowid,context_id,revision,payload FROM context_preferences WHERE scope_id=?1`},
	{"execution_preferences", `SELECT rowid,scope_id,revision,payload FROM execution_preferences WHERE scope_id=?1`},
	{"desired_execution_locations", `SELECT rowid,context_id,revision,payload FROM desired_execution_locations WHERE scope_id=?1`},
	{"locations", `SELECT l.rowid,l.id,l.revision,l.payload FROM locations l WHERE EXISTS (SELECT 1 FROM workers w WHERE w.scope_id=?1 AND json_extract(w.payload,'$.location_id')=l.id) OR EXISTS (SELECT 1 FROM desired_execution_locations d WHERE d.scope_id=?1 AND (d.location_id=l.id OR json_extract(d.payload,'$.root_location_id')=l.id)) OR EXISTS (SELECT 1 FROM execution_preferences p,json_each(p.payload,'$.selected_location_ids') j WHERE p.scope_id=?1 AND j.value=l.id)`},
	{"raw_ingress", `SELECT sequence,id,revision,payload FROM raw_ingress WHERE json_extract(payload,'$.route.scope_id')=?1 AND json_extract(payload,'$.envelope.chat_type')='p2p'`},
	{"ingress_observations", `SELECT i.rowid,json_array(i.app_id,i.generation,i.event_id),0,i.payload FROM ingress_observations i JOIN raw_ingress r ON r.id=i.ingress_id WHERE json_extract(r.payload,'$.route.scope_id')=?1 AND json_extract(r.payload,'$.envelope.chat_type')='p2p'`},
	{"messages", `SELECT rowid,id,revision,payload FROM messages WHERE scope_id=?1`},
	{"inbox", `SELECT rowid,id,revision,payload FROM inbox WHERE scope_id=?1`},
	{"workers", `SELECT rowid,id,revision,payload FROM workers WHERE scope_id=?1`},
	{"attempts", `SELECT rowid,id,revision,payload FROM attempts WHERE scope_id=?1`},
	{"migration_stop_evidence", `SELECT c.rowid,c.id,0,json_object('content_ref',c.id) FROM content c JOIN attempts a ON c.id='private-stop:'||a.id AND c.scope_id=a.scope_id WHERE a.scope_id=?1`},
	{"migration_intake_evidence", `SELECT c.rowid,c.id,0,json_object('content_ref',c.id) FROM content c WHERE c.scope_id=?1 AND c.id LIKE 'migration-intake-proof:%'`},
	{"attempt_inputs", `SELECT i.rowid,json_array(i.attempt_id,i.inbox_id),0,json_object('attempt_id',i.attempt_id,'inbox_id',i.inbox_id) FROM attempt_inputs i JOIN attempts a ON a.id=i.attempt_id WHERE a.scope_id=?1`},
	{"attempt_input_admissions", `SELECT i.rowid,i.id,coalesce(json_extract(i.payload,'$.revision'),0),i.payload FROM attempt_input_admissions i JOIN attempts a ON a.id=i.attempt_id WHERE a.scope_id=?1`},
	{"outcome_reports", `SELECT o.rowid,o.attempt_id,coalesce(json_extract(o.payload,'$.revision'),0),o.payload FROM outcome_reports o JOIN attempts a ON a.id=o.attempt_id WHERE a.scope_id=?1`},
	{"outcomes", `SELECT o.rowid,o.attempt_id,0,o.payload FROM outcomes o JOIN attempts a ON a.id=o.attempt_id WHERE a.scope_id=?1`},
	{"operations", `SELECT rowid,id,revision,payload FROM operations WHERE scope_id=?1`},
	{"outbox", `SELECT rowid,id,revision,payload FROM outbox WHERE scope_id=?1`},
	{"memories", `SELECT rowid,id,revision,payload FROM memories WHERE scope_id=?1 AND json_extract(payload,'$.scope.kind')='personal' AND json_extract(payload,'$.scope.principal_id')=(SELECT principal_id FROM scopes WHERE id=?1) AND json_extract(payload,'$.scope.role_id')=(SELECT role_id FROM scopes WHERE id=?1)`},
	{"sharing_grants", `SELECT rowid,id,revision,payload FROM sharing_grants WHERE scope_id=?1`},
	{"carrier_registrations", `SELECT c.rowid,c.incarnation,0,json_object('incarnation',c.incarnation,'worker_id',c.worker_id,'instance_id',c.instance_id,'connected',c.connected,'registration',json(c.payload)) FROM carrier_registrations c JOIN workers w ON w.id=c.worker_id WHERE w.scope_id=?1`},
	{"carrier_occupancy", `SELECT c.rowid,json_array(c.instance_id,c.instance_generation,c.process_generation),0,json_object('instance_id',c.instance_id,'instance_generation',c.instance_generation,'process_generation',c.process_generation,'attempt_id',c.attempt_id) FROM carrier_occupancy c JOIN attempts a ON a.id=c.attempt_id WHERE a.scope_id=?1`},
	{"resource_occupancy", `SELECT r.rowid,r.resource_key,0,json_object('resource_key',r.resource_key,'attempt_id',r.attempt_id,'generation',r.generation) FROM resource_occupancy r JOIN attempts a ON a.id=r.attempt_id WHERE a.scope_id=?1`},
	{"runtime_controller_occupancy", `SELECT c.rowid,c.resource_key,0,json_object('resource_key',c.resource_key,'worker_id',c.worker_id,'location_generation',c.location_generation,'controller_generation',c.controller_generation) FROM runtime_controller_occupancy c JOIN workers w ON w.id=c.worker_id WHERE w.scope_id=?1`},
	{"runtime_carrier_processes", `SELECT p.rowid,p.incarnation,0,p.payload FROM runtime_carrier_processes p JOIN carrier_registrations c ON c.incarnation=p.incarnation JOIN workers w ON w.id=c.worker_id WHERE w.scope_id=?1`},
	{"runtime_gates", `SELECT g.rowid,g.worker_id,coalesce(json_extract(g.payload,'$.revision'),0),g.payload FROM runtime_gates g JOIN workers w ON w.id=g.worker_id WHERE w.scope_id=?1`},
	{"runtime_gate_sequences", `SELECT g.rowid,g.worker_id,g.revision,json_object('worker_id',g.worker_id,'revision',g.revision) FROM runtime_gate_sequences g JOIN workers w ON w.id=g.worker_id WHERE w.scope_id=?1`},
	{"runtime_continuations", `SELECT n.rowid,json_array(n.incarnation,n.session_id),0,n.payload FROM runtime_continuations n JOIN carrier_registrations c ON c.incarnation=n.incarnation JOIN workers w ON w.id=c.worker_id WHERE w.scope_id=?1`},
	{"native_commands", `SELECT n.rowid,n.command_id,0,n.payload FROM native_commands n JOIN carrier_registrations c ON c.incarnation=n.incarnation JOIN workers w ON w.id=c.worker_id WHERE w.scope_id=?1`},
	{"runtime_model_catalogs", `SELECT n.rowid,n.command_id,0,n.payload FROM runtime_model_catalogs n JOIN carrier_registrations c ON c.incarnation=n.incarnation JOIN workers w ON w.id=c.worker_id WHERE w.scope_id=?1`},
	{"native_turns", `SELECT n.rowid,json_array(n.carrier_incarnation,n.session_id,n.turn_id),0,n.payload FROM native_turns n JOIN attempts a ON a.id=n.attempt_id WHERE a.scope_id=?1`},
	{"runtime_receipts", `SELECT r.sequence,json_array(r.carrier_incarnation,r.sequence),0,json_object('incarnation',r.carrier_incarnation,'sequence',r.sequence,'payload_hash',r.payload_hash,'instance_id',r.instance_id,'received_at',r.received_at,'event',json(r.payload)) FROM runtime_receipts r JOIN carrier_registrations c ON c.incarnation=r.carrier_incarnation JOIN workers w ON w.id=c.worker_id WHERE w.scope_id=?1`},
	{"runtime_quarantine", `SELECT q.rowid,json_array(q.incarnation,q.sequence),0,json_object('incarnation',q.incarnation,'sequence',q.sequence,'session_id',q.session_id,'turn_id',q.turn_id,'reason',q.reason,'resolved',q.resolved) FROM runtime_quarantine q JOIN carrier_registrations c ON c.incarnation=q.incarnation JOIN workers w ON w.id=c.worker_id WHERE w.scope_id=?1`},
	{"quiescence_receipts", `SELECT q.rowid,q.attempt_id,0,q.payload FROM quiescence_receipts q JOIN attempts a ON a.id=q.attempt_id WHERE a.scope_id=?1`},
	{"team_ui_views", `SELECT rowid,id,revision,payload FROM team_ui_views WHERE scope_id=?1`},
	{"private_execution_display", `SELECT d.rowid,d.id,d.revision,d.payload FROM private_execution_display d WHERE json_extract(d.payload,'$.Binding.scopeId')=?1`},
	{"team_private_reactions", `SELECT rowid,id,coalesce(json_extract(payload,'$.revision'),0),payload FROM team_private_reactions WHERE json_extract(payload,'$.scope_id')=?1`},
	{"team_private_reaction_actions", `SELECT rowid,id,coalesce(json_extract(payload,'$.revision'),0),payload FROM team_private_reaction_actions WHERE json_extract(payload,'$.scope_id')=?1`},
	{"team_platform_observations", `SELECT p.rowid,p.id,0,p.payload FROM team_platform_observations p WHERE p.id IN (SELECT id FROM team_private_reaction_actions WHERE json_extract(payload,'$.scope_id')=?1) OR EXISTS (SELECT 1 FROM messages m WHERE m.scope_id=?1 AND json_extract(m.payload,'$.platform_key.tenant')=p.tenant AND json_extract(m.payload,'$.platform_key.chat_id')=p.chat_id AND json_extract(m.payload,'$.platform_key.message_id')=p.message_id) OR EXISTS (SELECT 1 FROM team_ui_views v WHERE v.scope_id=?1 AND json_extract(v.payload,'$.tenant')=p.tenant AND json_extract(v.payload,'$.chat_id')=p.chat_id AND json_extract(v.payload,'$.external_message_id')=p.message_id) OR EXISTS (SELECT 1 FROM outbox o JOIN raw_ingress r ON json_extract(r.payload,'$.route.scope_id')=o.scope_id WHERE o.scope_id=?1 AND json_extract(o.payload,'$.external_message_id')=p.message_id AND json_extract(o.payload,'$.target')=p.chat_id AND json_extract(r.payload,'$.envelope.chat_type')='p2p' AND json_extract(r.payload,'$.envelope.tenant')=p.tenant AND json_extract(r.payload,'$.envelope.chat_id')=p.chat_id)`},
	{"private_shell_operations", `SELECT rowid,id,coalesce(json_extract(payload,'$.revision'),0),payload FROM private_shell_operations WHERE json_extract(payload,'$.scope_id')=?1`},
	{"private_commands", `SELECT rowid,id,revision,payload FROM private_commands WHERE scope_id=?1`},
	{"menu_interactions", `SELECT rowid,id,revision,payload FROM menu_interactions WHERE json_extract(payload,'$.scope_id')=?1`},
	{"human_interactions", `SELECT h.rowid,h.id,h.revision,h.payload FROM human_interactions h WHERE h.principal_id=(SELECT principal_id FROM scopes WHERE id=?1) AND EXISTS (SELECT 1 FROM raw_ingress r WHERE json_extract(r.payload,'$.route.scope_id')=?1 AND json_extract(r.payload,'$.envelope.chat_type')='p2p' AND json_extract(r.payload,'$.envelope.tenant')=json_extract(h.payload,'$.envelope.tenant') AND json_extract(r.payload,'$.envelope.chat_id')=json_extract(h.payload,'$.envelope.chat_id') AND json_extract(r.payload,'$.gateway.app_id')=json_extract(h.payload,'$.gateway.app_id'))`},
	{"native_ui_requests", `SELECT rowid,id,revision,payload FROM native_ui_requests WHERE json_extract(payload,'$.scope_id')=?1`},
	{"platform_message_mappings", `SELECT p.rowid,json_array(p.tenant,p.chat_id,p.message_id),0,p.payload FROM platform_message_mappings p WHERE json_extract(p.payload,'$.scope_id')=?1`},
	{"pause_gates", `SELECT rowid,id,revision,payload FROM pause_gates WHERE scope_id=?1`},
	{"native_maintenance", `SELECT n.rowid,n.id,n.revision,n.payload FROM native_maintenance n JOIN workers w ON w.id=n.worker_id WHERE w.scope_id=?1`},
	{"native_upgrades", `SELECT n.rowid,n.id,coalesce(json_extract(n.payload,'$.revision'),0),json_object('id',n.id,'host_id',n.host_id,'stage',json_extract(n.payload,'$.stage'),'revision',json_extract(n.payload,'$.revision'),'target_version',json_extract(n.payload,'$.target_version'),'installation_fingerprint',json_extract(n.payload,'$.installation_fingerprint'),'last_error',json_extract(n.payload,'$.last_error'),'relevant_workers',json((SELECT json_group_array(json(j.value)) FROM json_each(n.payload,'$.workers') j JOIN workers w ON w.id=json_extract(j.value,'$.id') WHERE w.scope_id=?1))) FROM native_upgrades n WHERE json_extract(n.payload,'$.stage')<>'completed' AND EXISTS (SELECT 1 FROM workers w JOIN locations l ON l.id=json_extract(w.payload,'$.location_id') WHERE w.scope_id=?1 AND json_extract(l.payload,'$.host_id')=n.host_id)`},
	{"session_goal_intents", `SELECT rowid,id,coalesce(json_extract(payload,'$.revision'),0),payload FROM session_goal_intents WHERE json_extract(payload,'$.scope_id')=?1`},
	{"private_instruction_adoptions", `SELECT rowid,id,coalesce(json_extract(payload,'$.revision'),0),payload FROM private_instruction_adoptions WHERE personal_scope_id=?1`},
	{"native_thread_token_usage", `SELECT n.rowid,json_array(n.incarnation,n.session_id),0,n.payload FROM native_thread_token_usage n JOIN carrier_registrations c ON c.incarnation=n.incarnation JOIN workers w ON w.id=c.worker_id WHERE w.scope_id=?1`},
	{"automation_policies", `SELECT p.rowid,json_array(p.context_id,p.kind),p.revision,p.payload FROM automation_policies p JOIN contexts c ON c.id=p.context_id WHERE c.scope_id=?1`},
	{"automation_episodes", `SELECT p.rowid,p.id,coalesce(json_extract(p.payload,'$.revision'),0),p.payload FROM automation_episodes p JOIN contexts c ON c.id=p.context_id WHERE c.scope_id=?1`},
	{"maintenance_admission_blocks", `SELECT b.rowid,b.resource_key,0,json_object('resource_key',b.resource_key,'maintenance_id',b.maintenance_id) FROM maintenance_admission_blocks b JOIN native_maintenance m ON m.id=b.maintenance_id JOIN workers w ON w.id=m.worker_id WHERE w.scope_id=?1`},
	{"work_migration_units", `SELECT rowid,json_array(migration_id,unit_key),0,json_object('migration_id',migration_id,'unit_key',unit_key,'principal_id',principal_id,'role_id',role_id,'scope_id',scope_id,'context_id',context_id) FROM work_migration_units WHERE scope_id=?1`},
	{"work_migration_records", `SELECT rowid,json_array(migration_id,record_key),revision,json_object('migration_id',migration_id,'record_key',record_key,'unit_key',unit_key,'kind',kind,'payload',json(payload),'state',state,'reason',reason,'scope_id',scope_id,'context_id',context_id,'owner',owner,'revision',revision) FROM work_migration_records WHERE scope_id=?1`},
	{"work_migration_native_owners", `SELECT n.rowid,n.native_key,0,json_object('native_key',n.native_key,'migration_id',n.migration_id,'unit_key',n.unit_key,'principal_id',n.principal_id,'role_id',n.role_id,'worker_id',n.worker_id) FROM work_migration_native_owners n JOIN workers w ON w.id=n.worker_id WHERE w.scope_id=?1`},
	{"work_legacy_observations", `SELECT o.id,CAST(o.id AS TEXT),0,json_object('id',o.id,'instance_id',o.instance_id,'kind',o.kind,'payload_hash',o.payload_hash,'observed_at',o.observed_at,'payload_omitted_reason','instance_observation_may_cover_other_owners') FROM work_legacy_observations o WHERE EXISTS (SELECT 1 FROM workers w WHERE w.scope_id=?1 AND json_extract(w.payload,'$.instance_id')=o.instance_id)`},
	{"work_migration_resource_fences", `SELECT f.rowid,json_array(f.migration_id,f.record_key,f.resource_key),0,json_object('resource_key',f.resource_key,'migration_id',f.migration_id,'record_key',f.record_key,'reason',f.reason,'evidence',json(f.evidence),'released',f.released,'resolution',json(f.resolution)) FROM work_migration_resource_fences f JOIN work_migration_records r ON r.migration_id=f.migration_id AND r.record_key=f.record_key WHERE r.scope_id=?1`},
}
